import { ComponentWrapper, createWrapper, ElementWrapper } from "@cloudscape-design/test-utils-core/selectors";
import ButtonWrapper from '../button/index.js';
import InputWrapper from '../input/index.js';
import buttonStyles from '../../../button/styles.selectors.js';
import categoryStyles from '../../../button-dropdown/category-elements/styles.selectors.js';
import itemStyles from '../../../button-dropdown/item-element/styles.selectors.js';
import styles from '../../../button-dropdown/styles.selectors.js';
import testUtilStyles from '../../../button-dropdown/test-classes/styles.selectors.js';
import dropdownStyles from '../../../dropdown/styles.selectors.js';
import inputStyles from '../../../input/styles.selectors.js';
import footerStyles from '../../../internal/components/dropdown-status/styles.selectors.js';

// The status of the root list and the status of an expanded group carry distinct markers, so a lookup
// never falls through from one to the other.
const statusScopeSelector = (expandedGroup: boolean) => `.${expandedGroup ? testUtilStyles['group-status'] : testUtilStyles['root-status']}`;
function getItemSelector({
  disabled
}: {
  disabled?: boolean;
}): string {
  let selector = `.${itemStyles['item-element']}`;
  if (disabled === true) {
    selector += `.${itemStyles.disabled}`;
  } else if (disabled === false) {
    selector += `:not(.${itemStyles.disabled})`;
  }
  return selector;
}
export default class ButtonDropdownWrapper extends ComponentWrapper {
  static rootSelector: string = styles['button-dropdown'];
  findNativeButton() {
    return this.findByClassName(styles['dropdown-trigger'])!.findByClassName(styles['test-utils-button-trigger'])!;
  }
  findTriggerButton() {
    return this.findByClassName(styles['dropdown-trigger'])?.findComponent(`.${buttonStyles.button}`, ButtonWrapper) ?? null;
  }
  findMainAction() {
    return this.findByClassName(styles['split-trigger'])?.findComponent(`.${buttonStyles.button}`, ButtonWrapper) ?? null;
  }
  findOpenDropdown() {
    return createWrapper().find(`.${dropdownStyles.dropdown}[data-open=true]`);
  }

  /**
   * Finds an item in the open dropdown by item id. Returns null if there is no open dropdown.
   *
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   *
   * Supported options:
   * * `disabled` (boolean) - Use it to find the disabled or non-disabled item.
   */
  findItemById(id: string, options: {
    disabled?: boolean;
  } = {}) {
    const itemSelector = `${getItemSelector(options)}[data-testid="${id}"]`;
    return this.findOpenDropdown()?.find(itemSelector) || this.find(itemSelector);
  }

  /**
   * Finds `checked` value of item in the open dropdown by item id. Returns null if there is no open dropdown or the item is not a checkbox item.
   *
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   */

  /**
   * Finds an expandable category in the open dropdown by category id. Returns null if there is no open dropdown.
   *
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   */
  findExpandableCategoryById(id: string) {
    const expandableCategorySelector = `.${categoryStyles.expandable}[data-testid="${id}"]`;
    return this.findOpenDropdown()?.find(expandableCategorySelector) || this.find(expandableCategorySelector);
  }

  /**
   * Finds the highlighted item in the open dropdown. Returns null if there is no open dropdown.
   *
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   */
  findHighlightedItem() {
    const highlightedItemSelector = `.${itemStyles['item-element']}.${itemStyles.highlighted}`;
    return this.findOpenDropdown()?.find(highlightedItemSelector) || this.find(highlightedItemSelector);
  }

  /**
   * Finds all the items in the open dropdown. Returns empty array if there is no open dropdown.
   *
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   *
   * Supported options:
   * * `disabled` (boolean) - Use it to find all disabled or non-disabled items.
   */
  findItems(options: {
    disabled?: boolean;
  } = {}) {
    const selector = getItemSelector(options);
    return this.findOpenDropdown()?.findAll(selector) || [];
  }

  /**
   * Finds the disabled reason tooltip for a dropdown item. Returns null if no disabled item with `disabledReason` is highlighted.
   */
  findDisabledReason() {
    return createWrapper().find(`[data-testid="button-dropdown-disabled-reason"]`);
  }

  /**
   * Finds the filtering input rendered inside the open dropdown when filtering is enabled.
   * Returns null if there is no open dropdown or filtering is not enabled.
   *
   * This utility does not open the dropdown. To find the filtering input, call `openDropdown()` first.
   */
  findFilteringInput() {
    return this.findOpenDropdown()?.findComponent(`.${inputStyles['input-container']}`, InputWrapper) ?? null;
  }

  /**
   * Finds the error recovery button when item loading fails.
   * Set `expandedGroupDropdown` to true to access the recovery button of an expanded group.
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   */
  findErrorRecoveryButton(options = {
    expandedGroupDropdown: false
  }) {
    return this.findOpenDropdown()?.find(`${statusScopeSelector(options.expandedGroupDropdown)} .${footerStyles.recovery}`) ?? null;
  }

  /**
   * Finds the status displayed at the footer of the dropdown.
   * Set `expandedGroupDropdown` to true to access the status of an expanded group.
   * This utility does not open the dropdown. To find dropdown items, call `openDropdown()` first.
   */
  findStatusIndicator(options = {
    expandedGroupDropdown: false
  }) {
    return this.findOpenDropdown()?.find(`${statusScopeSelector(options.expandedGroupDropdown)} .${footerStyles.root}`) ?? null;
  }

  /**
   * Finds the footer region rendered at the bottom of the open dropdown. When filtering is enabled and text is
   * entered, this contains content rendered by filteringResultsText if there are matching items and the `noMatch`
   * content if there are none. Returns null if there is no open dropdown or the footer is not displayed.
   *
   * This utility does not open the dropdown. To find the footer region, call `openDropdown()` first.
   */
  findFooterRegion() {
    return this.findOpenDropdown()?.find(`${statusScopeSelector(false)} .${footerStyles.root}`) ?? null;
  }
}